-- #260. Run with application writers stopped and backup verified. No data is deleted or converted.
-- Missing historical evidence stays NULL; coverage/limit are not implicitly accredited.
SET NAMES utf8mb4;
DELIMITER //
BEGIN NOT ATOMIC
 IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE') THEN
 IF EXISTS (SELECT 1 FROM MOVIMIENTO_CUENTA_CORRIENTE m LEFT JOIN CUENTA_CORRIENTE c USING(id_cuenta_corriente)
 LEFT JOIN PEDIDO p ON p.id_pedido=m.id_pedido LEFT JOIN PAGO a ON a.id_pago=m.id_pago
 WHERE c.id_cuenta_corriente IS NULL OR (m.id_pedido IS NOT NULL AND p.id_pedido IS NULL) OR (m.id_pago IS NOT NULL AND a.id_pago IS NULL) OR BINARY m.moneda <> BINARY 'USD' OR m.monto<=0 OR m.tipo_movimiento NOT IN ('CARGO','ABONO') OR m.estado NOT IN ('ACREDITADO','ANULADO')
 OR NOT ((m.tipo_movimiento='CARGO' AND m.id_pedido IS NOT NULL AND m.id_pago IS NULL AND p.id_cliente=c.id_cliente)
 OR (m.tipo_movimiento='ABONO' AND m.id_pago IS NOT NULL AND m.id_pedido IS NULL AND a.id_cuenta_corriente=c.id_cuenta_corriente AND BINARY a.estado=BINARY 'ACREDITADO')))
 OR EXISTS(SELECT 1 FROM MOVIMIENTO_CUENTA_CORRIENTE GROUP BY id_pedido HAVING id_pedido IS NOT NULL AND COUNT(*)>1)
 OR EXISTS(SELECT 1 FROM MOVIMIENTO_CUENTA_CORRIENTE GROUP BY id_pago HAVING id_pago IS NOT NULL AND COUNT(*)>1)
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='FER260_CONFLICTO_MOVIMIENTOS: conciliar moneda, referencias, titularidad o duplicados'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='IMPUTACION_MOVIMIENTO_CUENTA') THEN
 IF EXISTS(SELECT 1 FROM IMPUTACION_MOVIMIENTO_CUENTA i LEFT JOIN MOVIMIENTO_CUENTA_CORRIENTE c ON c.id_movimiento_cuenta=i.id_cargo
 LEFT JOIN MOVIMIENTO_CUENTA_CORRIENTE a ON a.id_movimiento_cuenta=i.id_abono
 WHERE c.id_movimiento_cuenta IS NULL OR a.id_movimiento_cuenta IS NULL OR i.id_cuenta_corriente<>c.id_cuenta_corriente OR i.id_cuenta_corriente<>a.id_cuenta_corriente
 OR c.tipo_movimiento<>'CARGO' OR a.tipo_movimiento<>'ABONO' OR i.monto_imputado<=0 OR i.estado NOT IN ('VIGENTE','ANULADA')
 OR (i.estado='VIGENTE' AND (c.estado<>'ACREDITADO' OR a.estado<>'ACREDITADO')))
 OR EXISTS(SELECT 1 FROM IMPUTACION_MOVIMIENTO_CUENTA i JOIN MOVIMIENTO_CUENTA_CORRIENTE m ON m.id_movimiento_cuenta=i.id_cargo WHERE i.estado='VIGENTE' GROUP BY i.id_cargo,m.monto HAVING SUM(i.monto_imputado)>m.monto)
 OR EXISTS(SELECT 1 FROM IMPUTACION_MOVIMIENTO_CUENTA i JOIN MOVIMIENTO_CUENTA_CORRIENTE m ON m.id_movimiento_cuenta=i.id_abono WHERE i.estado='VIGENTE' GROUP BY i.id_abono,m.monto HAVING SUM(i.monto_imputado)>m.monto)
 OR EXISTS(SELECT 1 FROM IMPUTACION_MOVIMIENTO_CUENTA WHERE estado='VIGENTE' GROUP BY id_cargo,id_abono HAVING COUNT(*)>1)
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='FER260_CONFLICTO_IMPUTACIONES: conciliar sin eliminar historial'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='CUENTA_CORRIENTE' AND COLUMN_NAME='cobertura') THEN
 IF EXISTS(SELECT 1 FROM CUENTA_CORRIENTE WHERE cobertura NOT IN ('COMPLETA','PARCIAL','NO_ACREDITADA') OR (plazo_dias IS NOT NULL AND plazo_dias NOT IN (30,60)))
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='FER260_CONFLICTO_CUENTA: cobertura o plazo invalidos'; END IF; END IF;
CREATE TABLE IF NOT EXISTS MOVIMIENTO_CUENTA_CORRIENTE (
    id_movimiento_cuenta INT NOT NULL AUTO_INCREMENT,
    id_cuenta_corriente INT NOT NULL,
    tipo_movimiento VARCHAR(20) COLLATE utf8mb4_bin NOT NULL,
    origen VARCHAR(50) NOT NULL,
    id_pedido INT NULL,
    id_pago INT NULL,
    monto DECIMAL(12,2) NOT NULL,
    moneda VARCHAR(3) NOT NULL DEFAULT 'USD',
    fecha_efectiva DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_incorporacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_vencimiento DATETIME NULL,
    estado VARCHAR(30) COLLATE utf8mb4_bin NOT NULL DEFAULT 'ACREDITADO',
    motivo_invalidacion TEXT NULL,
    autorizado_por VARCHAR(200) NULL,
    observaciones TEXT NULL,
    fecha_base_civil DATE NULL,
    plazo_aplicado INT NULL,
    vence_el DATE NULL,
    huella_registro CHAR(64) NULL,
    evidencia_origen LONGTEXT NULL,
    monto_original DECIMAL(12,2) NULL,
    moneda_original VARCHAR(3) NULL,
    id_cotizacion INT NULL,
    tasa_historica DECIMAL(20,8) NULL,
    evento_invalidacion VARCHAR(100) COLLATE utf8mb4_bin NULL,
    invalidado_utc DATETIME(3) NULL,
    UNIQUE KEY uq_movimiento_invalidacion (evento_invalidacion),
    PRIMARY KEY (id_movimiento_cuenta),
    UNIQUE KEY uq_movimiento_pedido (id_pedido),
    UNIQUE KEY uq_movimiento_pago (id_pago),
    KEY idx_movimiento_cuenta (id_cuenta_corriente),
    KEY idx_movimiento_cuenta_estado (id_cuenta_corriente, estado),
    CONSTRAINT fk_movimiento_cuenta FOREIGN KEY (id_cuenta_corriente)
        REFERENCES CUENTA_CORRIENTE (id_cuenta_corriente) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_movimiento_pedido FOREIGN KEY (id_pedido)
        REFERENCES PEDIDO (id_pedido) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_movimiento_pago FOREIGN KEY (id_pago)
        REFERENCES PAGO (id_pago) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT chk_movimiento_tipo CHECK (tipo_movimiento IN ('CARGO', 'ABONO')),
    CONSTRAINT chk_movimiento_monto CHECK (monto > 0),
    CONSTRAINT chk_movimiento_moneda CHECK (BINARY moneda = BINARY 'USD'),
    CONSTRAINT chk_movimiento_estado CHECK (estado IN ('ACREDITADO', 'ANULADO')),
    CONSTRAINT chk_movimiento_referencia CHECK ((tipo_movimiento = 'CARGO' AND id_pedido IS NOT NULL AND id_pago IS NULL) OR (tipo_movimiento = 'ABONO' AND id_pago IS NOT NULL AND id_pedido IS NULL)),
    CONSTRAINT chk_movimiento_fecha CHECK ((fecha_base_civil IS NULL AND plazo_aplicado IS NULL AND vence_el IS NULL) OR (tipo_movimiento = 'CARGO' AND fecha_base_civil IS NOT NULL AND plazo_aplicado IS NOT NULL AND plazo_aplicado IN (30,60) AND vence_el IS NOT NULL AND vence_el = DATE_ADD(fecha_base_civil, INTERVAL plazo_aplicado DAY))),
    CONSTRAINT chk_movimiento_original CHECK ((monto_original IS NULL AND moneda_original IS NULL AND evidencia_origen IS NULL) OR (monto_original IS NOT NULL AND monto_original > 0 AND moneda_original IS NOT NULL AND moneda_original IN ('USD','ARS') AND evidencia_origen IS NOT NULL AND JSON_VALID(evidencia_origen) AND (moneda_original = 'USD' OR (id_cotizacion IS NOT NULL AND tasa_historica IS NOT NULL AND tasa_historica > 0)))),
    CONSTRAINT fk_movimiento_cotizacion FOREIGN KEY (id_cotizacion) REFERENCES COTIZACION (id_cotizacion) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS IMPUTACION_MOVIMIENTO_CUENTA (
    id_imputacion INT NOT NULL AUTO_INCREMENT,
    id_cuenta_corriente INT NOT NULL,
    id_cargo INT NOT NULL,
    id_abono INT NOT NULL,
    monto_imputado DECIMAL(12,2) NOT NULL,
    fecha_imputacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    estado VARCHAR(20) COLLATE utf8mb4_bin NOT NULL DEFAULT 'VIGENTE',
    revision BIGINT UNSIGNED NULL,
    evento VARCHAR(100) COLLATE utf8mb4_bin NULL,
    evento_sustitucion VARCHAR(100) COLLATE utf8mb4_bin NULL,
    invalidada_utc DATETIME(3) NULL,
    UNIQUE KEY uq_imputacion_revision (id_cargo,id_abono,revision),
    PRIMARY KEY (id_imputacion),
    KEY idx_imputacion_cargo (id_cargo),
    KEY idx_imputacion_abono (id_abono),
    CONSTRAINT fk_imp_cuenta FOREIGN KEY (id_cuenta_corriente)
        REFERENCES CUENTA_CORRIENTE (id_cuenta_corriente) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_imp_cargo FOREIGN KEY (id_cargo)
        REFERENCES MOVIMIENTO_CUENTA_CORRIENTE (id_movimiento_cuenta) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_imp_abono FOREIGN KEY (id_abono)
        REFERENCES MOVIMIENTO_CUENTA_CORRIENTE (id_movimiento_cuenta) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT chk_imp_monto CHECK (monto_imputado > 0),
    CONSTRAINT chk_imp_estado CHECK (estado IN ('VIGENTE', 'ANULADA'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
 ALTER TABLE CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS cobertura VARCHAR(20) NOT NULL DEFAULT 'NO_ACREDITADA', ADD COLUMN IF NOT EXISTS plazo_dias INT NULL DEFAULT NULL;
 ALTER TABLE CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS moneda_limite VARCHAR(3) NULL;
 ALTER TABLE CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS evidencia_limite VARCHAR(1000) NULL;
 ALTER TABLE CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS evidencia_plazo VARCHAR(1000) NULL;
 ALTER TABLE CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS evidencia_cobertura VARCHAR(1000) NULL;
 ALTER TABLE CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS cobertura_desde_utc DATETIME(3) NULL;
 ALTER TABLE CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS origen_datos VARCHAR(10) COLLATE utf8mb4_bin NOT NULL DEFAULT 'REAL';
 ALTER TABLE CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS revision BIGINT UNSIGNED NOT NULL DEFAULT 0;
 ALTER TABLE PAGO ADD COLUMN IF NOT EXISTS moneda VARCHAR(3) NULL;
 ALTER TABLE PAGO ADD COLUMN IF NOT EXISTS fecha_acreditacion_utc DATETIME(3) NULL;
 ALTER TABLE PAGO ADD COLUMN IF NOT EXISTS evidencia_acreditacion VARCHAR(1000) NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS fecha_base_civil DATE NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS plazo_aplicado INT NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS vence_el DATE NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS huella_registro CHAR(64) NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS evidencia_origen LONGTEXT NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS monto_original DECIMAL(12,2) NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS moneda_original VARCHAR(3) NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS id_cotizacion INT NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS tasa_historica DECIMAL(20,8) NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS evento_invalidacion VARCHAR(100) COLLATE utf8mb4_bin NULL;
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD COLUMN IF NOT EXISTS invalidado_utc DATETIME(3) NULL;
 ALTER TABLE IMPUTACION_MOVIMIENTO_CUENTA ADD COLUMN IF NOT EXISTS revision BIGINT UNSIGNED NULL;
 ALTER TABLE IMPUTACION_MOVIMIENTO_CUENTA ADD COLUMN IF NOT EXISTS evento VARCHAR(100) COLLATE utf8mb4_bin NULL;
 ALTER TABLE IMPUTACION_MOVIMIENTO_CUENTA ADD COLUMN IF NOT EXISTS evento_sustitucion VARCHAR(100) COLLATE utf8mb4_bin NULL;
 ALTER TABLE IMPUTACION_MOVIMIENTO_CUENTA ADD COLUMN IF NOT EXISTS invalidada_utc DATETIME(3) NULL;
 ALTER TABLE CUENTA_CORRIENTE MODIFY plazo_dias INT NULL DEFAULT NULL;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_cuenta_cobertura') THEN
 ALTER TABLE CUENTA_CORRIENTE DROP CONSTRAINT chk_cuenta_cobertura, ADD CONSTRAINT chk_cuenta_cobertura CHECK (cobertura IN ('COMPLETA', 'PARCIAL', 'NO_ACREDITADA'));
 ELSE ALTER TABLE CUENTA_CORRIENTE ADD CONSTRAINT chk_cuenta_cobertura CHECK (cobertura IN ('COMPLETA', 'PARCIAL', 'NO_ACREDITADA')); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_cuenta_plazo') THEN
 ALTER TABLE CUENTA_CORRIENTE DROP CONSTRAINT chk_cuenta_plazo, ADD CONSTRAINT chk_cuenta_plazo CHECK (plazo_dias IS NULL OR plazo_dias IN (30, 60));
 ELSE ALTER TABLE CUENTA_CORRIENTE ADD CONSTRAINT chk_cuenta_plazo CHECK (plazo_dias IS NULL OR plazo_dias IN (30, 60)); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_cuenta_moneda_limite') THEN
 ALTER TABLE CUENTA_CORRIENTE DROP CONSTRAINT chk_cuenta_moneda_limite, ADD CONSTRAINT chk_cuenta_moneda_limite CHECK (moneda_limite IS NULL OR moneda_limite = 'USD');
 ELSE ALTER TABLE CUENTA_CORRIENTE ADD CONSTRAINT chk_cuenta_moneda_limite CHECK (moneda_limite IS NULL OR moneda_limite = 'USD'); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_cuenta_origen') THEN
 ALTER TABLE CUENTA_CORRIENTE DROP CONSTRAINT chk_cuenta_origen, ADD CONSTRAINT chk_cuenta_origen CHECK (origen_datos IN ('REAL', 'DEMO'));
 ELSE ALTER TABLE CUENTA_CORRIENTE ADD CONSTRAINT chk_cuenta_origen CHECK (origen_datos IN ('REAL', 'DEMO')); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='PAGO' AND CONSTRAINT_NAME='chk_pago_moneda') THEN
 ALTER TABLE PAGO DROP CONSTRAINT chk_pago_moneda, ADD CONSTRAINT chk_pago_moneda CHECK (moneda IS NULL OR moneda IN ('USD', 'ARS'));
 ELSE ALTER TABLE PAGO ADD CONSTRAINT chk_pago_moneda CHECK (moneda IS NULL OR moneda IN ('USD', 'ARS')); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_movimiento_tipo') THEN
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE DROP CONSTRAINT chk_movimiento_tipo, ADD CONSTRAINT chk_movimiento_tipo CHECK (tipo_movimiento IN ('CARGO', 'ABONO'));
 ELSE ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD CONSTRAINT chk_movimiento_tipo CHECK (tipo_movimiento IN ('CARGO', 'ABONO')); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_movimiento_monto') THEN
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE DROP CONSTRAINT chk_movimiento_monto, ADD CONSTRAINT chk_movimiento_monto CHECK (monto > 0);
 ELSE ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD CONSTRAINT chk_movimiento_monto CHECK (monto > 0); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_movimiento_moneda') THEN
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE DROP CONSTRAINT chk_movimiento_moneda, ADD CONSTRAINT chk_movimiento_moneda CHECK (BINARY moneda = BINARY 'USD');
 ELSE ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD CONSTRAINT chk_movimiento_moneda CHECK (BINARY moneda = BINARY 'USD'); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_movimiento_estado') THEN
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE DROP CONSTRAINT chk_movimiento_estado, ADD CONSTRAINT chk_movimiento_estado CHECK (estado IN ('ACREDITADO', 'ANULADO'));
 ELSE ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD CONSTRAINT chk_movimiento_estado CHECK (estado IN ('ACREDITADO', 'ANULADO')); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_movimiento_referencia') THEN
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE DROP CONSTRAINT chk_movimiento_referencia, ADD CONSTRAINT chk_movimiento_referencia CHECK ((tipo_movimiento = 'CARGO' AND id_pedido IS NOT NULL AND id_pago IS NULL) OR (tipo_movimiento = 'ABONO' AND id_pago IS NOT NULL AND id_pedido IS NULL));
 ELSE ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD CONSTRAINT chk_movimiento_referencia CHECK ((tipo_movimiento = 'CARGO' AND id_pedido IS NOT NULL AND id_pago IS NULL) OR (tipo_movimiento = 'ABONO' AND id_pago IS NOT NULL AND id_pedido IS NULL)); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_movimiento_fecha') THEN
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE DROP CONSTRAINT chk_movimiento_fecha, ADD CONSTRAINT chk_movimiento_fecha CHECK ((fecha_base_civil IS NULL AND plazo_aplicado IS NULL AND vence_el IS NULL) OR (tipo_movimiento = 'CARGO' AND fecha_base_civil IS NOT NULL AND plazo_aplicado IS NOT NULL AND plazo_aplicado IN (30,60) AND vence_el IS NOT NULL AND vence_el = DATE_ADD(fecha_base_civil, INTERVAL plazo_aplicado DAY)));
 ELSE ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD CONSTRAINT chk_movimiento_fecha CHECK ((fecha_base_civil IS NULL AND plazo_aplicado IS NULL AND vence_el IS NULL) OR (tipo_movimiento = 'CARGO' AND fecha_base_civil IS NOT NULL AND plazo_aplicado IS NOT NULL AND plazo_aplicado IN (30,60) AND vence_el IS NOT NULL AND vence_el = DATE_ADD(fecha_base_civil, INTERVAL plazo_aplicado DAY))); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND CONSTRAINT_NAME='chk_movimiento_original') THEN
 ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE DROP CONSTRAINT chk_movimiento_original, ADD CONSTRAINT chk_movimiento_original CHECK ((monto_original IS NULL AND moneda_original IS NULL AND evidencia_origen IS NULL) OR (monto_original IS NOT NULL AND monto_original > 0 AND moneda_original IS NOT NULL AND moneda_original IN ('USD','ARS') AND evidencia_origen IS NOT NULL AND JSON_VALID(evidencia_origen) AND (moneda_original = 'USD' OR (id_cotizacion IS NOT NULL AND tasa_historica IS NOT NULL AND tasa_historica > 0))));
 ELSE ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD CONSTRAINT chk_movimiento_original CHECK ((monto_original IS NULL AND moneda_original IS NULL AND evidencia_origen IS NULL) OR (monto_original IS NOT NULL AND monto_original > 0 AND moneda_original IS NOT NULL AND moneda_original IN ('USD','ARS') AND evidencia_origen IS NOT NULL AND JSON_VALID(evidencia_origen) AND (moneda_original = 'USD' OR (id_cotizacion IS NOT NULL AND tasa_historica IS NOT NULL AND tasa_historica > 0)))); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='IMPUTACION_MOVIMIENTO_CUENTA' AND CONSTRAINT_NAME='chk_imp_monto') THEN
 ALTER TABLE IMPUTACION_MOVIMIENTO_CUENTA DROP CONSTRAINT chk_imp_monto, ADD CONSTRAINT chk_imp_monto CHECK (monto_imputado > 0);
 ELSE ALTER TABLE IMPUTACION_MOVIMIENTO_CUENTA ADD CONSTRAINT chk_imp_monto CHECK (monto_imputado > 0); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='IMPUTACION_MOVIMIENTO_CUENTA' AND CONSTRAINT_NAME='chk_imp_estado') THEN
 ALTER TABLE IMPUTACION_MOVIMIENTO_CUENTA DROP CONSTRAINT chk_imp_estado, ADD CONSTRAINT chk_imp_estado CHECK (estado IN ('VIGENTE', 'ANULADA'));
 ELSE ALTER TABLE IMPUTACION_MOVIMIENTO_CUENTA ADD CONSTRAINT chk_imp_estado CHECK (estado IN ('VIGENTE', 'ANULADA')); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND INDEX_NAME='uq_movimiento_pedido') THEN ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE DROP INDEX uq_movimiento_pedido, ADD UNIQUE KEY uq_movimiento_pedido (id_pedido); ELSE ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD UNIQUE KEY uq_movimiento_pedido (id_pedido); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND INDEX_NAME='uq_movimiento_pago') THEN ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE DROP INDEX uq_movimiento_pago, ADD UNIQUE KEY uq_movimiento_pago (id_pago); ELSE ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD UNIQUE KEY uq_movimiento_pago (id_pago); END IF;
 IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND INDEX_NAME='uq_movimiento_invalidacion') THEN ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE DROP INDEX uq_movimiento_invalidacion, ADD UNIQUE KEY uq_movimiento_invalidacion (evento_invalidacion); ELSE ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD UNIQUE KEY uq_movimiento_invalidacion (evento_invalidacion); END IF;
 IF NOT EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND INDEX_NAME='idx_movimiento_cuenta') THEN ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD  KEY idx_movimiento_cuenta (id_cuenta_corriente); END IF;
 IF NOT EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='MOVIMIENTO_CUENTA_CORRIENTE' AND INDEX_NAME='idx_movimiento_cuenta_estado') THEN ALTER TABLE MOVIMIENTO_CUENTA_CORRIENTE ADD  KEY idx_movimiento_cuenta_estado (id_cuenta_corriente, estado); END IF;
 IF NOT EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='IMPUTACION_MOVIMIENTO_CUENTA' AND INDEX_NAME='idx_imputacion_cargo') THEN ALTER TABLE IMPUTACION_MOVIMIENTO_CUENTA ADD  KEY idx_imputacion_cargo (id_cargo); END IF;
