DELIMITER //
CREATE OR REPLACE TRIGGER fer260_cuenta_revision BEFORE UPDATE ON CUENTA_CORRIENTE FOR EACH ROW
SET NEW.revision = OLD.revision + 1//
CREATE OR REPLACE TRIGGER fer260_imputacion_insert BEFORE INSERT ON IMPUTACION_MOVIMIENTO_CUENTA FOR EACH ROW
BEGIN
 DECLARE owner_id INT; DECLARE cargo_amount DECIMAL(12,2); DECLARE abono_amount DECIMAL(12,2);
 DECLARE cargo_account INT; DECLARE abono_account INT; DECLARE cargo_type VARCHAR(20); DECLARE abono_type VARCHAR(20);
 DECLARE cargo_state VARCHAR(30); DECLARE abono_state VARCHAR(30); DECLARE assigned_cargo DECIMAL(32,2); DECLARE assigned_abono DECIMAL(32,2); DECLARE pairs INT;

 IF NEW.estado='VIGENTE' THEN
 SELECT id_cuenta_corriente INTO owner_id FROM CUENTA_CORRIENTE WHERE id_cuenta_corriente=NEW.id_cuenta_corriente FOR UPDATE;
 SELECT id_cuenta_corriente,tipo_movimiento,estado,monto INTO cargo_account,cargo_type,cargo_state,cargo_amount FROM MOVIMIENTO_CUENTA_CORRIENTE WHERE id_movimiento_cuenta=NEW.id_cargo FOR UPDATE;
 SELECT id_cuenta_corriente,tipo_movimiento,estado,monto INTO abono_account,abono_type,abono_state,abono_amount FROM MOVIMIENTO_CUENTA_CORRIENTE WHERE id_movimiento_cuenta=NEW.id_abono FOR UPDATE;
 IF cargo_account IS NULL OR abono_account IS NULL OR cargo_account<>owner_id OR abono_account<>owner_id OR cargo_type<>'CARGO' OR abono_type<>'ABONO' OR cargo_state<>'ACREDITADO' OR abono_state<>'ACREDITADO'
 OR NEW.revision IS NULL OR NEW.evento IS NULL OR CHAR_LENGTH(TRIM(NEW.evento))=0
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='FER260_IMPUTACION_REFERENCIA_INVALIDA'; END IF;
 SELECT COALESCE(SUM(monto_imputado),0) INTO assigned_cargo FROM IMPUTACION_MOVIMIENTO_CUENTA WHERE id_cargo=NEW.id_cargo AND estado='VIGENTE'  LOCK IN SHARE MODE;
 SELECT COALESCE(SUM(monto_imputado),0) INTO assigned_abono FROM IMPUTACION_MOVIMIENTO_CUENTA WHERE id_abono=NEW.id_abono AND estado='VIGENTE'  LOCK IN SHARE MODE;
 SELECT COUNT(*) INTO pairs FROM IMPUTACION_MOVIMIENTO_CUENTA WHERE id_cargo=NEW.id_cargo AND id_abono=NEW.id_abono AND estado='VIGENTE'  LOCK IN SHARE MODE;
 IF assigned_cargo+NEW.monto_imputado>cargo_amount OR assigned_abono+NEW.monto_imputado>abono_amount OR pairs>0
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='FER260_IMPUTACION_EXCESO_O_DUPLICADA'; END IF;
 END IF;
END//
CREATE OR REPLACE TRIGGER fer260_imputacion_update BEFORE UPDATE ON IMPUTACION_MOVIMIENTO_CUENTA FOR EACH ROW
BEGIN
 DECLARE owner_id INT; DECLARE cargo_amount DECIMAL(12,2); DECLARE abono_amount DECIMAL(12,2);
 DECLARE cargo_account INT; DECLARE abono_account INT; DECLARE cargo_type VARCHAR(20); DECLARE abono_type VARCHAR(20);
 DECLARE cargo_state VARCHAR(30); DECLARE abono_state VARCHAR(30); DECLARE assigned_cargo DECIMAL(32,2); DECLARE assigned_abono DECIMAL(32,2); DECLARE pairs INT;
 IF NEW.id_cuenta_corriente<>OLD.id_cuenta_corriente OR NEW.id_cargo<>OLD.id_cargo OR NEW.id_abono<>OLD.id_abono OR NEW.monto_imputado<>OLD.monto_imputado
 OR NOT(NEW.revision<=>OLD.revision) OR NOT(NEW.evento<=>OLD.evento) OR (OLD.estado='ANULADA' AND NEW.estado<>'ANULADA')
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='FER260_HISTORIAL_INMUTABLE'; END IF;
 IF NEW.estado='VIGENTE' THEN
 SELECT id_cuenta_corriente INTO owner_id FROM CUENTA_CORRIENTE WHERE id_cuenta_corriente=NEW.id_cuenta_corriente FOR UPDATE;
 SELECT id_cuenta_corriente,tipo_movimiento,estado,monto INTO cargo_account,cargo_type,cargo_state,cargo_amount FROM MOVIMIENTO_CUENTA_CORRIENTE WHERE id_movimiento_cuenta=NEW.id_cargo FOR UPDATE;
 SELECT id_cuenta_corriente,tipo_movimiento,estado,monto INTO abono_account,abono_type,abono_state,abono_amount FROM MOVIMIENTO_CUENTA_CORRIENTE WHERE id_movimiento_cuenta=NEW.id_abono FOR UPDATE;
 IF cargo_account IS NULL OR abono_account IS NULL OR cargo_account<>owner_id OR abono_account<>owner_id OR cargo_type<>'CARGO' OR abono_type<>'ABONO' OR cargo_state<>'ACREDITADO' OR abono_state<>'ACREDITADO'
 OR NEW.revision IS NULL OR NEW.evento IS NULL OR CHAR_LENGTH(TRIM(NEW.evento))=0
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='FER260_IMPUTACION_REFERENCIA_INVALIDA'; END IF;
 SELECT COALESCE(SUM(monto_imputado),0) INTO assigned_cargo FROM IMPUTACION_MOVIMIENTO_CUENTA WHERE id_cargo=NEW.id_cargo AND estado='VIGENTE' AND id_imputacion<>OLD.id_imputacion LOCK IN SHARE MODE;
 SELECT COALESCE(SUM(monto_imputado),0) INTO assigned_abono FROM IMPUTACION_MOVIMIENTO_CUENTA WHERE id_abono=NEW.id_abono AND estado='VIGENTE' AND id_imputacion<>OLD.id_imputacion LOCK IN SHARE MODE;
 SELECT COUNT(*) INTO pairs FROM IMPUTACION_MOVIMIENTO_CUENTA WHERE id_cargo=NEW.id_cargo AND id_abono=NEW.id_abono AND estado='VIGENTE' AND id_imputacion<>OLD.id_imputacion LOCK IN SHARE MODE;
 IF assigned_cargo+NEW.monto_imputado>cargo_amount OR assigned_abono+NEW.monto_imputado>abono_amount OR pairs>0
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='FER260_IMPUTACION_EXCESO_O_DUPLICADA'; END IF;
 END IF;
END//
DELIMITER ;
